 class MessageStorageBase(object):
     def __init__(self, request):
         self.request = request
         self._messages = []
         self._level = None
         self._extra_tags = None
         self._next_id = 1

     def _get_next_id(self):
         self._next_id += 1
         return self._next_id - 1

     def _get_message(self, id):
         for message in self._messages:
             if message['id'] == id:
                 return message
         return None

     def _update_message(self, id, message):
         message = self._get_message(id)
         if message:
             message['message'] = message['message']
             message['level'] = message['level']
             message['extra_tags'] = message['extra_tags']
         else:
             self._messages.append(message)

     def add(self, message, level=None, extra_tags=None):
         if level is None:
             level = self._level
         if extra_tags is None:
             extra_tags = self._extra_tags
         message_id = self._get_next_id()
         message = {'id': message_id, 'message': message, 'level': level, 'extra_tags': extra_tags}
         self._update_message(message_id, message)
         self._messages.append(message)

     def flush(self):
         self._messages = []
         self._level = None
         self._extra_tags = None

     def _get_messages(self):
         return self._messages

     def _set_messages(self, value):
         self._messages = value

     messages = property(_get_messages, _set_messages)

     def _get_level(self):
         return self._level

     def _set_level(self, value):
         self._level = value

     level = property(_get_level, _set_level)

     def _get_extra_tags(self):
         return self._extra_tags

     def _set_extra_tags(self, value):
         self._extra_tags = value

     extra_tags = property(_get_extra_tags, _set_extra_tags)

